const bySrc = Object.fromEntries(SITE_IMAGES.map(i => [i.src, i])) as Record<string, SiteImage>
export const img = (src: string): SiteImage => {
  const i = bySrc[src]
  if (!i) throw new Error(`Unknown site image ${src}`)
  return i
}

